package main

import (
	"os"
	"runtime"
	"runtime/pprof"
)

var keep [][]byte

func work() {
	for i := 0; i < 1000; i++ {
		b := make([]byte, 1024)
		if i%100 == 0 {
			keep = append(keep, b)
		}
	}
}

func main() {
	runtime.MemProfileRate = 1
	work()
	f, _ := os.Create("heap.pb.gz")
	pprof.Lookup("heap").WriteTo(f, 0)
	f.Close()
}
